package io.github.jesterportfolio.hearth.economy;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.economy.EconomyContent.*;
import static io.github.jesterportfolio.hearth.economy.EconomyEngine.*;
import java.util.*;
import java.nio.file.*;
import java.lang.management.ManagementFactory;

class EconomyEngineTest {
    static EconomyContent demo(){try(var r=new java.io.InputStreamReader(Objects.requireNonNull(EconomyEngineTest.class.getResourceAsStream("/economy-demo.properties")),java.nio.charset.StandardCharsets.UTF_8)){var p=new Properties();p.load(r);return parse(p);}catch(Exception e){throw new AssertionError(e);}}
    final UUID realm=new UUID(2,3);final EconomyContent c=demo();
    @Test void impactSpreadAndNoRoundTripProfit(){for(long stock:new long[]{0,1,20,100,500,10000})for(int q:new int[]{1,8,32,4096}){var before=new Market(stock+q,300,0);long cost=quote(c,"iron_ingot",before,q,true);var after=new Market(stock,300,1);long proceeds=quote(c,"iron_ingot",after,q,false);assertTrue(cost>proceeds);assertEquals(cost,quoteReference(c,"iron_ingot",before,q,true));assertEquals(proceeds,quoteReference(c,"iron_ingot",after,q,false));}var m=new Market(100,300,0);assertTrue(quote(c,"iron_ingot",m,32,true)>32*quote(c,"iron_ingot",m,1,true));}
    @Test void extremeInputsRejected(){assertThrows(IllegalArgumentException.class,()->new Market(-1,1,0));assertThrows(IllegalArgumentException.class,()->quote(c,"iron_ingot",new Market(1,300,0),2,true));assertThrows(IllegalArgumentException.class,()->quote(c,"iron_ingot",new Market(5000,300,0),4097,true));assertThrows(IllegalArgumentException.class,()->new Policy(0,1,1,1,1,10000));}
    @Test void transportArrivesOnlyAtDueTickAndConservesOre(){var simple=new EconomyContent(c.regions(),c.goods(),Map.of(),List.of(),c.routes(),Map.of(),c.policy(),5000,"PAUSE",8,0);var s=initial(simple);long total=s.markets().values().stream().mapToLong(Market::stock).sum();for(int i=1;i<=6;i++){s=advance(realm,simple,s).state();long all=s.markets().values().stream().mapToLong(Market::stock).sum()+s.shipments().stream().mapToLong(Shipment::quantity).sum();assertEquals(total,all);assertEquals(i<4?200:200+(i-3)*10,s.markets().get(new Key("capital","iron_ore")).stock());}assertEquals(3,s.shipments().size());}
    @Test void manufactureConsumesExactlyAndStopsWhenMissing(){var simple=new EconomyContent(c.regions(),c.goods(),Map.of(),List.of(c.facilities().get(1)),List.of(),Map.of(),c.policy(),5000,"PAUSE",8,0);var m=new HashMap<>(initial(simple).markets());m.put(new Key("capital","iron_ingot"),new Market(0,300,0));m.put(new Key("capital","iron_ore"),new Market(7,100,0));var next=advance(realm,simple,new State(0,m,List.of(),List.of())).state();assertEquals(3,next.markets().get(new Key("capital","iron_ingot")).stock());assertEquals(1,next.markets().get(new Key("capital","iron_ore")).stock());assertEquals(3,advance(realm,simple,next).state().markets().get(new Key("capital","iron_ingot")).stock());}
    @Test void productionShockAndRecoveryBounded(){var s=initial(c);s=new State(0,s.markets(),List.of(),List.of(new Active(new UUID(4,1),"mine_collapse",1,25)));long highest=100;for(int i=0;i<120;i++){var next=advance(realm,c,s).state();for(var key:c.cells()){long old=s.markets().get(key).price(),now=next.markets().get(key).price();assertTrue(Math.abs(now-old)<=Math.max(1,old*c.policy().maxStep()/10000));}s=next;highest=Math.max(highest,s.markets().get(new Key("mine","iron_ore")).price());}assertTrue(highest>150);assertTrue(s.markets().get(new Key("mine","iron_ore")).price()<=102);assertTrue(s.events().isEmpty());}
    @Test void roadBlockAndDemandShock(){var base=initial(c);var blocked=advance(realm,c,new State(0,base.markets(),List.of(),List.of(new Active(new UUID(1,1),"road_block",1,12))));assertTrue(blocked.departed().isEmpty());var shock=advance(realm,c,new State(0,base.markets(),List.of(),List.of(new Active(new UUID(1,2),"demand_surge",1,12)))).state();assertTrue(shock.markets().get(new Key("capital","iron_ingot")).price()>300);}
    @Test void tickSpanningSelfTradeCannotPumpAnchor(){var baseline=initial(c);var m=new HashMap<>(baseline.markets());m.put(new Key("capital","iron_ingot"),new Market(10,300,1));var bought=new State(0,m,List.of(),List.of());for(int i=0;i<4;i++){baseline=advance(realm,c,baseline).state();bought=advance(realm,c,bought).state();assertEquals(baseline.markets().get(new Key("capital","iron_ingot")).price(),bought.markets().get(new Key("capital","iron_ingot")).price());}}
    @Test void duplicateAndInvalidContent(){assertThrows(IllegalArgumentException.class,()->new EconomyContent(List.of("mine","mine"),c.goods(),Map.of(),List.of(),List.of(),Map.of(),c.policy(),5000,"PAUSE",8,0));assertThrows(IllegalArgumentException.class,()->new EconomyContent(c.regions(),c.goods(),Map.of(),List.of(c.facilities().getFirst(),c.facilities().getFirst()),List.of(),Map.of(),c.policy(),5000,"PAUSE",8,0));assertThrows(IllegalArgumentException.class,()->new EconomyContent(c.regions(),c.goods(),Map.of(),List.of(),List.of(new Route("bad","missing","capital","iron_ore",1,1)),Map.of(),c.policy(),5000,"PAUSE",8,0));}
    @Test void offlineCapAndPauseDoNotAssumeOperationalPolicy(){assertEquals(0,EconomyStore.offlineTicks(c,0,100000));var catchup=new EconomyContent(c.regions(),c.goods(),c.demand(),c.facilities(),c.routes(),c.events(),c.policy(),5000,"CATCH_UP_CAPPED",8,0);assertEquals(8,EconomyStore.offlineTicks(catchup,0,100000));assertEquals(0,EconomyStore.offlineTicks(catchup,100000,100000));assertThrows(RuntimeException.class,()->EconomyStore.offlineTicks(c,2,1));}
    @Test void ninetyDaysDeterministicAndScaledCost()throws Exception{
        long start=System.nanoTime(),cpu=ManagementFactory.getThreadMXBean().getCurrentThreadCpuTime();var s=initial(c);for(int tick=0;tick<90*24;tick++)s=advance(realm,c,s).state();long small=System.nanoTime()-start;var repeat=initial(c);for(int tick=0;tick<90*24;tick++)repeat=advance(realm,c,repeat).state();assertEquals(s,repeat);assertTrue(s.shipments().size()<=3);assertEquals(2160,s.tick());
        var regions=new ArrayList<String>();for(int i=0;i<32;i++)regions.add("r"+i);var goods=new HashMap<String,Good>();for(int i=0;i<16;i++)goods.put("g"+i,new Good("g"+i,"STONE",100,200));var large=new EconomyContent(regions,goods,Map.of(),List.of(),List.of(),Map.of(),c.policy(),5000,"PAUSE",8,0);start=System.nanoTime();var scaled=initial(large);for(int i=0;i<2160;i++)scaled=advance(realm,large,scaled).state();long largeNs=System.nanoTime()-start;
        var market=new Market(10000,300,0);for(int i=0;i<50;i++)quote(c,"iron_ingot",market,4096,true);start=System.nanoTime();long check=0;for(int i=0;i<200;i++)check+=quote(c,"iron_ingot",market,4096,true);long fast=System.nanoTime()-start;start=System.nanoTime();long reference=0;for(int i=0;i<200;i++)reference+=quoteReference(c,"iron_ingot",market,4096,true);long slow=System.nanoTime()-start;assertEquals(check,reference);
        Files.createDirectories(Path.of("build/economy"));Files.writeString(Path.of("build/economy/performance.json"),"{\"virtual_days\":90,\"ticks\":2160,\"small_cells\":4,\"small_ns\":"+small+",\"large_cells\":512,\"large_ns\":"+largeNs+",\"quote_200_ns\":"+fast+",\"reference_200_ns\":"+slow+",\"cpu_ns\":"+(ManagementFactory.getThreadMXBean().getCurrentThreadCpuTime()-cpu)+",\"heap_used_bytes\":"+(Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory())+"}");
    }
}
